effect.shader:
void main() {
    // Idade do anel dentro do ciclo atual (0 = acabou de nascer, period = acabou).
    float idade = fract(acTime / max(period, 1e-4)) * period;
    float raio = idade * speed;

    // Força decai linear com a idade: nasce forte, some no fim.
    float forcaDoPulso = 1.0 - clamp(idade / max(period, 1e-4), 0.0, 1.0);

    vec2 p = vec2(acScreenNorm.x * acAspect, acScreenNorm.y);
    vec2 centro = vec2(centerAt.x * acAspect, centerAt.y);
    vec2 delta = p - centro;
    float d = length(delta);
    vec2 direcao = d > 1e-4 ? delta / d : vec2(0.0);

    // Pulso: proximidade da distância ao raio. Gaussiano no desvio.
    float proximidade = exp(-pow((d - raio) / max(ringWidth, 1e-4), 2.0));
    float empurrar = proximidade * strength * forcaDoPulso;

    vec2 uvAfastado = acScreenNorm + direcao * empurrar;
    vec4 cor = texture(inputImg, uvAfastado);

    // Pinta o anel visível por cima (opcional via ringColor.a).
    float desenhoDoAnel = exp(-pow((d - raio) / max(ringWidth * 0.5, 1e-4), 2.0)) * forcaDoPulso;
    vec3 halo = ringColor.rgb * desenhoDoAnel * ringGlow * ringColor.a;
    cor.rgb = 1.0 - (1.0 - cor.rgb) * (1.0 - halo);

    fragColor = cor;
}
